body.script:
(function () {

    var COLORS = {
        active: '#198754',
        no_signal: '#fd7e14',
        offline: '#6c757d'
    };


    var map =
        L.map('nk-map').setView(
            [22.5, 79],
            5
        );


    L.tileLayer(
        'https://tile.openstreetmap.org/{z}/{x}/{y}.png',
        {
            maxZoom: 19,
            attribution: '(c) OpenStreetMap contributors'
        }
    ).addTo(map);


    var layer =
        L.layerGroup().addTo(map);


    var first = true;


    function cell(tr, text) {

        var td =
            document.createElement('td');

        td.textContent = text;

        tr.appendChild(td);

    }


    function load() {

        fetch(
            '/nk_salesperson/admin/tracking/live',
            {
                credentials: 'same-origin'
            }
        )

        .then(function (r) {
            return r.json();
        })

        .then(function (data) {

            layer.clearLayers();

            var bounds = [];

            var body =
                document.getElementById(
                    'nk-live-body'
                );

            body.innerHTML = '';


            data.employees.forEach(
                function (e) {

                    var tr =
                        document.createElement('tr');


                    cell(
                        tr,
                        e.name
                    );


                    cell(
                        tr,
                        e.status_label
                    );


                    cell(
                        tr,
                        e.last_time || '-'
                    );


                    cell(
                        tr,
                        e.accuracy
                            ? Math.round(e.accuracy) + ' m'
                            : '-'
                    );


                    cell(
                        tr,
                        e.address || '-'
                    );


                    var linkCell =
                        document.createElement('td');


                    if (e.maps) {

                        var link =
                            document.createElement('a');

                        link.href = e.maps;

                        link.target = '_blank';

                        link.rel = 'noopener';

                        link.textContent = 'Open';

                        linkCell.appendChild(link);

                    }


                    tr.appendChild(linkCell);

                    body.appendChild(tr);


                    if (e.lat === null) {
                        return;
                    }


                    var color =
                        COLORS[e.status];


                    var marker =
                        L.circleMarker(
                            [
                                e.lat,
                                e.lng
                            ],
                            {
                                radius: 10,
                                color: color,
                                fillColor: color,
                                fillOpacity: 0.85
                            }
                        ).addTo(layer);


                    var label =
                        document.createElement(
                            'span'
                        );


                    label.textContent =
                        e.name;


                    marker.bindTooltip(
                        label,
                        {
                            permanent: true,
                            direction: 'top'
                        }
                    );


                    bounds.push(
                        [
                            e.lat,
                            e.lng
                        ]
                    );

                }
            );


            if (first) {

                if (bounds.length) {

                    map.fitBounds(
                        bounds,
                        {
                            maxZoom: 15,
                            padding: [40, 40]
                        }
                    );

                }

                first = false;

            }

        });

    }


    load();

    setInterval(
        load,
        30000
    );

})();

(function () {

    var pts =
        JSON.parse(
            document.getElementById(
                'nk-data'
            ).dataset.points || '[]'
        );


    var map =
        L.map('nk-map').setView(
            [22.5, 79],
            5
        );


    L.tileLayer(
        'https://tile.openstreetmap.org/{z}/{x}/{y}.png',
        {
            maxZoom: 19,
            attribution: '(c) OpenStreetMap contributors'
        }
    ).addTo(map);


    if (pts.length) {

        var latlngs =
            pts.map(
                function (p) {
                    return [
                        p.lat,
                        p.lng
                    ];
                }
            );


        L.polyline(
            latlngs,
            {
                color: '#0d6efd',
                weight: 3
            }
        ).addTo(map);


        pts.forEach(
            function (p, i) {

                var color = '#0d6efd';


                if (p.visit) {
                    color = '#fd7e14';
                }


                if (i === 0) {
                    color = '#198754';
                }


                if (i === pts.length - 1) {
                    color = '#dc3545';
                }


                var marker =
                    L.circleMarker(
                        [
                            p.lat,
                            p.lng
                        ],
                        {
                            radius:
                                p.visit ? 9 : 6,
                            color: color,
                            fillColor: color,
                            fillOpacity: 0.9
                        }
                    ).addTo(map);


                var tip =
                    document.createElement(
                        'div'
                    );


                tip.textContent =
                    p.time
                    + (
                        p.address
                            ? ' - ' + p.address
                            : ''
                    )
                    + (
                        p.visit
                            ? ' - ' + p.visit
                            : ''
                    );


                marker.bindTooltip(tip);

            }
        );


        map.fitBounds(
            latlngs,
            {
                padding: [40, 40],
                maxZoom: 16
            }
        );

    }

})();

                    (function () {

                        var dataElement =
                            document.getElementById(
                                'nk-today-data'
                            );


                        var points = [];


                        if (dataElement) {

                            try {

                                points = JSON.parse(
                                    dataElement.dataset.points || '[]'
                                );

                            } catch (error) {

                                console.error(
                                    'Unable to read tracking points:',
                                    error
                                );

                                points = [];

                            }

                        }


                        var map =
                            L.map(
                                'nk-today-map'
                            ).setView(
                                [22.5, 79],
                                5
                            );


                        L.tileLayer(
                            'https://tile.openstreetmap.org/{z}/{x}/{y}.png',
                            {
                                maxZoom: 19,
                                attribution:
                                    '(c) OpenStreetMap contributors'
                            }
                        ).addTo(map);


                        if (!points.length) {

                            map.setView(
                                [29.2183, 79.5130],
                                11
                            );

                            return;

                        }


                        var latlngs =
                            points.map(
                                function (p) {

                                    return [
                                        p.lat,
                                        p.lng
                                    ];

                                }
                            );


                        /* Route */

                        L.polyline(
                            latlngs,
                            {
                                color: '#0d6efd',
                                weight: 5,
                                opacity: 0.75
                            }
                        ).addTo(map);


                        /* Location markers */

                        points.forEach(
                            function (p, index) {

                                var color =
                                    '#0d6efd';

                                var radius =
                                    6;


                                /* First point */

                                if (index === 0) {

                                    color =
                                        '#198754';

                                    radius =
                                        10;

                                }


                                /* Latest point */

                                if (
                                    index ===
                                    points.length - 1
                                ) {

                                    color =
                                        '#dc3545';

                                    radius =
                                        10;

                                }


                                /* Visit point */

                                if (p.visit) {

                                    color =
                                        '#fd7e14';

                                    radius =
                                        9;

                                }


                                var marker =
                                    L.circleMarker(
                                        [
                                            p.lat,
                                            p.lng
                                        ],
                                        {
                                            radius:
                                                radius,
                                            color:
                                                color,
                                            fillColor:
                                                color,
                                            fillOpacity:
                                                0.9,
                                            weight:
                                                2
                                        }
                                    ).addTo(map);


                                var text =
                                    p.time || '';


                                if (p.address) {

                                    text +=
                                        ' - ' +
                                        p.address;

                                }


                                if (p.visit) {

                                    text +=
                                        ' - ' +
                                        p.visit;

                                }


                                marker.bindTooltip(
                                    text
                                );


                                marker.bindPopup(
                                    'Time: '
                                    + (p.time || '-')
                                    + '
'
                                    + 'Location: '
                                    + (p.location || '-')
                                    + '
'
                                    + 'Accuracy: '
                                    + (p.accuracy || '-')
                                    + ' m'
                                    + (
                                        p.visit
                                            ? '
Visit: '
                                              + p.visit
                                            : ''
                                    )
                                );

                            }
                        );


                        /* Fit complete route */

                        map.fitBounds(
                            latlngs,
                            {
                                padding: [40, 40],
                                maxZoom: 16
                            }
                        );

                    })();

(function () {

    var pts =
        JSON.parse(
            document.getElementById(
                'nk-data'
            ).dataset.points || '[]'
        );


    var map =
        L.map(
            'nk-map'
        ).setView(
            [22.5, 79],
            5
        );


    L.tileLayer(
        'https://tile.openstreetmap.org/{z}/{x}/{y}.png',
        {
            maxZoom: 19,
            attribution:
                '(c) OpenStreetMap contributors'
        }
    ).addTo(map);


    var routes = {};

    var all = [];


    pts.forEach(
        function (p) {

            var key =
                p.emp + '|' + p.day;


            if (!routes[key]) {

                routes[key] = {
                    color: p.color,
                    latlngs: []
                };

            }


            routes[key].latlngs.push(
                [
                    p.lat,
                    p.lng
                ]
            );


            all.push(
                [
                    p.lat,
                    p.lng
                ]
            );


            var marker =
                L.circleMarker(
                    [
                        p.lat,
                        p.lng
                    ],
                    {
                        radius:
                            p.visit ? 8 : 5,
                        color:
                            p.visit
                                ? '#000000'
                                : p.color,
                        weight:
                            p.visit ? 2 : 1,
                        fillColor:
                            p.color,
                        fillOpacity: 0.9
                    }
                ).addTo(map);


            var tip =
                document.createElement(
                    'div'
                );


            tip.textContent =
                p.emp
                + ' - '
                + p.time
                + (
                    p.address
                        ? ' - ' + p.address
                        : ''
                )
                + (
                    p.visit
                        ? ' - ' + p.visit
                        : ''
                );


            marker.bindTooltip(tip);

        }
    );


    Object.keys(routes).forEach(
        function (key) {

            L.polyline(
                routes[key].latlngs,
                {
                    color:
                        routes[key].color,
                    weight: 3,
                    opacity: 0.7
                }
            ).addTo(map);

        }
    );


    if (all.length) {

        map.fitBounds(
            all,
            {
                padding: [40, 40],
                maxZoom: 16
            }
        );

    }

})();
